205				t.Fatalf("record %d left the legacy JSON fingerprint family", idx+1)
206			}
207		}
208		for _, idx := range []int{2, 3} {
209			if got := fingerprintFor(&recs[idx]); got == legacyJSONFingerprint(&recs[idx]) {
210				t.Fatalf("record %d unexpectedly uses the JSON fingerprint", idx+1)
211			}
212		}
213	
214		// Policy content reads back byte for byte.
215		if !reflect.DeepEqual(recs[0].Change, &PolicyChange{Version: 1, Policies: []Policy{compatAllowPolicy}}) {
216			t.Fatalf("record 1 change = %+v", recs[0].Change)
217		}
218		if !reflect.DeepEqual(recs[2].Change, &PolicyChange{Version: 2, Policies: []Policy{compatInvalidPolicy}}) {
